<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
import AccountLayout from '../../layouts/AccountLayout.vue';
interface Entry { id: number; event: string; actor_id: number | null; subject_id: number | null; source: string; created_at: string; metadata: { from_role?: string; to_role?: string; entity_type?: string; entity_id?: number; from_status?: string; to_status?: string; changed_fields?: string[]; image_id?: number } }
defineProps<{ entries: { data: Entry[]; prev_page_url: string | null; next_page_url: string | null; current_page: number } }>();
const date = (value: string) => new Intl.DateTimeFormat('es-CR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Costa_Rica' }).format(new Date(value));
</script>
<template><Head title="Auditoría"/><AccountLayout title="Registro de actividad" section="admin"><p class="muted">Historial de seguridad. Horario de Costa Rica. Solo lectura.</p><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Actor / Cuenta</th><th>Origen</th><th>Detalle</th><th>Fecha</th></tr></thead><tbody><tr v-for="entry in entries.data" :key="entry.id"><td>{{ entry.event }}</td><td>{{ entry.actor_id ?? '—' }} / {{ entry.subject_id ?? '—' }}</td><td>{{ entry.source }}</td><td>{{ entry.metadata?.from_role ? `${entry.metadata.from_role} → ${entry.metadata.to_role}` : '—' }}</td><td>{{ date(entry.created_at) }}<small v-if="entry.metadata?.entity_type" class="block">{{ entry.metadata.entity_type }} #{{ entry.metadata.entity_id }} · {{ entry.metadata.from_status }} → {{ entry.metadata.to_status }} {{ entry.metadata.changed_fields?.join(', ') }}<span v-if="entry.metadata.image_id"> · Imagen #{{ entry.metadata.image_id }}</span></small></td></tr><tr v-if="!entries.data.length"><td colspan="5">Todavía no hay actividad registrada.</td></tr></tbody></table></div><nav class="pagination" aria-label="Páginas del registro"><Link v-if="entries.prev_page_url" :href="entries.prev_page_url">← Anterior</Link><span>Página {{ entries.current_page }}</span><Link v-if="entries.next_page_url" :href="entries.next_page_url">Siguiente →</Link></nav></AccountLayout></template>
